package com.tripmateai.repository; import com.tripmateai.entity.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import java.util.*; import java.math.BigDecimal;
public interface ExpenseRepository extends JpaRepository<Expense,Long> { Page<Expense> findByTrip(Trip trip,Pageable pageable); Optional<Expense> findByIdAndTrip(Long id,Trip trip); List<Expense> findByTrip(Trip trip); @Query("select coalesce(sum(e.amount), 0) from Expense e where e.user = :user") BigDecimal sumAmountByUser(@Param("user") User user); @Query("select coalesce(e.category.name, 'UNCATEGORIZED') as category, coalesce(sum(e.amount), 0) as total from Expense e where e.user = :user group by e.category.name order by sum(e.amount) desc") List<CategoryTotal> categoryTotalsByUser(@Param("user") User user); @Query(value="select date_format(expense_date, '%Y-%m') as month, coalesce(sum(amount), 0) as total from expenses where user_id = :userId group by date_format(expense_date, '%Y-%m') order by month",nativeQuery=true) List<MonthlyTotal> monthlyTotalsByUser(@Param("userId") Long userId); interface CategoryTotal {String getCategory(); BigDecimal getTotal();} interface MonthlyTotal {String getMonth(); BigDecimal getTotal();} }
